import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { acceptSessionFromUrl, storedSession, urlSession } from '@/lib/pilot/urlSession';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

/** True when a link carried a sign-in but this browser was already signed in, so the link was not used. */
export const urlSessionRefused = () => urlSession.refused;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: (url, params) => {
      // Error returns (an uninvited Google account, an expired link) are always read so the page can explain them.
      if (!params.access_token) return Boolean(params.error_description);
      return acceptSessionFromUrl(url, storedSession());
    },
  }
});
